content.css:
.cc-root {
  width: 100%;
  height: 100%;
  font-family: "Segoe UI", system-ui, sans-serif;
  color: #242424;
  background: linear-gradient(180deg, #FFFFFF 0%, #F8F9FB 100%);
  overflow: hidden;
  box-sizing: border-box;
}
.cc-container {
  position: relative;
  width: 100%;
  height: 100%;
  box-sizing: border-box;
  padding: 2px 2px 22px 2px;
  display: flex;
  flex-direction: column;
}
.cc-header {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 3px 6px;
  flex: 0 0 auto;
  border-bottom: 1px solid #E5E7EB;
  background: linear-gradient(180deg, #FFFFFF 0%, #F8F9FB 100%);
}
.cc-header__titles {
  display: flex;
  flex-direction: column;
  flex: 1 1 auto;
  min-width: 0;
}
.cc-header__title {
  font-weight: 600;
  color: #1F2A44;
  line-height: 1.2;
}
.cc-header__subtitle {
  color: #6C757D;
  line-height: 1.2;
}
.cc-header__info-wrap {
  position: relative;
}
.cc-header__info {
  width: 20px;
  height: 20px;
  border-radius: 50%;
  border: 1px solid #E5E7EB;
  background: #fff;
  color: #6C757D;
  font-style: italic;
  font-weight: 700;
  font-size: 12px;
  cursor: pointer;
  line-height: 1;
}
.cc-header__info:hover {
  background: #E8612A;
  color: #fff;
  border-color: #E8612A;
}
.cc-header__info-pop {
  position: absolute;
  right: 0;
  top: 26px;
  width: 280px;
  background: #fff;
  border: 1px solid #E5E7EB;
  border-radius: 6px;
  box-shadow: 0 6px 24px rgba(0, 0, 0, 0.12);
  padding: 12px 14px;
  z-index: 50;
}
.cc-header__info-title {
  font-weight: 600;
  color: #1F2A44;
  padding-bottom: 4px;
  border-bottom: 2px solid #E8612A;
  margin-bottom: 8px;
  font-size: 13px;
}
.cc-header__info-desc {
  font-size: 12px;
  color: #242424;
  margin-bottom: 8px;
  line-height: 1.4;
}
.cc-header__info-how {
  font-weight: 600;
  color: #6C757D;
  font-size: 11px;
  text-transform: uppercase;
  margin-bottom: 4px;
}
.cc-header__info-bullets {
  font-size: 12px;
  color: #242424;
  padding-left: 18px;
  margin: 0;
  line-height: 1.45;
}
.cc-header__info-bullets li {
  margin: 2px 0;
}
.cc-header__info-close {
  position: absolute;
  right: 6px;
  top: 4px;
  background: transparent;
  border: 0;
  font-size: 16px;
  color: #6C757D;
  cursor: pointer;
  line-height: 1;
}
.cc-header__info-close:hover {
  color: #E8612A;
}
.cc-body {
  display: flex;
  flex-direction: row;
  align-items: stretch;
  flex: 1 1 auto;
  min-height: 0;
  box-sizing: border-box;
}
.cc-body .cc-main {
  flex: 1 1 auto;
  min-width: 0;
  min-height: 0;
  padding: 2px 4px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
}
.cc-body--insight-hidden .cc-strip-toggle,
.cc-body--insight-hidden .cc-insight-panel {
  display: none !important;
}
.cc-body--insight-collapsed .cc-insight-panel {
  display: none;
}
.cc-body--insight-collapsed .cc-strip-toggle {
  width: 16px;
}
.cc-body--insight-expanded .cc-insight-panel {
  display: flex;
  flex-direction: column;
}
.cc-strip-toggle {
  width: 24px;
  background: #F8F9FB;
  border-left: 1px solid #E5E7EB;
  border-right: 1px solid #E5E7EB;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  color: #E8612A;
}
.cc-strip-toggle__arrow {
  font-size: 14px;
  padding: 4px 0;
}
.cc-strip-toggle__label {
  writing-mode: vertical-rl;
  transform: rotate(180deg);
  font-size: 10px;
  letter-spacing: 0.2em;
  color: #6C757D;
  text-transform: uppercase;
  margin-top: 6px;
}
.cc-strip-toggle:hover {
  background: #fbe3d9;
}
.cc-insight-panel {
  width: 250px;
  max-width: 320px;
  flex: 0 0 auto;
  padding: 10px 12px;
  background: linear-gradient(180deg, #FFFFFF 0%, #F8F9FB 100%);
  border-left: 1px solid #E5E7EB;
  box-sizing: border-box;
  overflow-y: auto;
  font-size: var(--cc-insight-font, 12px);
}
.cc-insight-panel__header {
  font-weight: 600;
  color: #1F2A44;
  font-size: var(--cc-insight-header-font, 13px);
  padding-bottom: 4px;
  margin-bottom: 8px;
  border-bottom: 2px solid var(--cc-insight-accent, #E8612A);
}
.cc-insight-panel__kpis {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 6px;
  margin-bottom: 8px;
}
.cc-insight-panel__smart {
  margin: 8px 0 0;
  line-height: 1.45;
}
.cc-insight-panel__smart strong {
  font-weight: 600;
  color: #1F2A44;
}
.cc-insight-panel__smart em {
  font-style: normal;
  font-weight: 600;
  color: var(--cc-insight-accent, #E8612A);
}
.cc-smart-section {
  margin-bottom: 8px;
}
.cc-smart-section__title {
  font-weight: 700;
  color: #1F2A44;
  font-size: calc(var(--cc-insight-font, 12px) + 0px);
  letter-spacing: 0.01em;
  padding: 2px 0;
  border-bottom: 1px solid #E5E7EB;
  margin-bottom: 4px;
}
.cc-smart-section__list {
  list-style: disc;
  padding-left: 16px;
  margin: 0;
}
.cc-smart-section__list li {
  margin: 2px 0;
}
.cc-smart-sublist {
  list-style: "→ ";
  padding-left: 14px;
  margin: 2px 0 4px;
  font-size: calc(var(--cc-insight-font, 12px) - 1px);
}
.cc-smart-sublist li {
  margin: 1px 0;
}
.cc-kpi {
  background: #fff;
  border: 1px solid #E5E7EB;
  border-left: 3px solid #E8612A;
  border-radius: 4px;
  padding: 6px 8px;
}
.cc-kpi__value {
  font-weight: 700;
  color: #1F2A44;
  font-size: calc(var(--cc-insight-font, 12px) + 2px);
}
.cc-kpi__label {
  color: #6C757D;
  font-size: calc(var(--cc-insight-font, 12px) - 1px);
}
.cc-notice {
  background: #fbe3d9;
  border: 1px solid #f4b69d;
  color: #c04615;
  border-radius: 3px;
  padding: 4px 8px;
  font-size: 11px;
  margin: 0 0 6px 0;
}
.cc-profile-label {
  font-weight: 600;
  color: #1F2A44;
  padding: 1px 6px 1px;
  font-size: 11px;
  line-height: 1.2;
  flex: 0 0 auto;
}
.cc-profile-label--cc {
  color: #dc5018;
}
.cc-arrow {
  text-align: center;
  color: #6C757D;
  font-size: 10px;
  padding: 2px 0;
  flex: 0 0 auto;
  line-height: 1.2;
}
.cc-diagnostic {
  background: #FFF7ED;
  border: 1px solid #FED7AA;
  color: #9A3412;
  border-radius: 3px;
  padding: 2px 8px;
  font-size: 11px;
  margin: 2px 0 4px;
  line-height: 1.3;
  flex: 0 0 auto;
}
.cc-legend {
  display: flex;
  flex-wrap: wrap;
  gap: 4px 12px;
  padding: 4px 4px 0;
  font-size: 10px;
  color: #6C757D;
  border-top: 1px dashed #E5E7EB;
  margin-top: 2px;
  flex: 0 0 auto;
}
.cc-legend__item {
  display: flex;
  align-items: center;
  gap: 4px;
}
.cc-legend__swatch {
  display: inline-block;
  width: 12px;
  height: 8px;
  border-radius: 2px;
}
.cc-legend__line {
  display: inline-block;
  width: 16px;
  height: 0;
  border-top: 1.5px dashed #444;
}
.cc-svg--profile .cc-axis path,
.cc-svg--profile .cc-axis line {
  stroke: #E5E7EB;
}
.cc-svg--profile .cc-axis text {
  fill: #6C757D;
}
.cc-svg--profile .cc-axis-title {
  fill: #1F2A44;
  font-weight: 600;
}
.cc-svg--profile .cc-block-label {
  fill: #fff;
  font-weight: 600;
  pointer-events: none;
  paint-order: stroke fill;
  stroke: rgba(0, 0, 0, 0.25);
  stroke-width: 0.4;
}
.cc-svg--profile .cc-block-sublabel {
  fill: rgba(255, 255, 255, 0.92);
  pointer-events: none;
  paint-order: stroke fill;
  stroke: rgba(0, 0, 0, 0.2);
  stroke-width: 0.3;
}
.cc-svg--profile .cc-capacity-label {
  fill: #444;
  font-weight: 600;
}
.cc-svg--profile .cc-conflict-label {
  font-weight: 700;
  paint-order: stroke fill;
  stroke: #fff;
  stroke-width: 2;
}
.cc-svg--profile .cc-makespan-label {
  fill: #6C757D;
  font-weight: 600;
}
.cc-chart {
  background: #fff;
  border: 1px solid #E5E7EB;
  border-radius: 3px;
  padding: 2px;
  box-sizing: border-box;
  flex: 0 0 auto;
  min-height: 80px;
  overflow: hidden;
}
.cc-chart svg {
  display: block;
  width: 100%;
  height: 100%;
}
.cc-svg {
  display: block;
}
.cc-axis path,
.cc-axis line {
  stroke: #E5E7EB;
}
.cc-axis text {
  fill: #6C757D;
}
.cc-task-label {
  fill: #242424;
  font-size: 11px;
}
.cc-task-label--pb {
  fill: #1F2A44;
  font-weight: 600;
}
.cc-bar {
  stroke: rgba(0, 0, 0, 0.06);
  stroke-width: 1;
}
.cc-fb {
  stroke: rgba(0, 0, 0, 0.08);
  stroke-width: 1;
}
.cc-pb {
  stroke: rgba(0, 0, 0, 0.1);
  stroke-width: 1;
}
.cc-strip {
  margin-top: 3px;
  background: #fff;
  border: 1px solid #E5E7EB;
  border-radius: 3px;
  padding: 2px;
  flex: 0 0 auto;
  max-height: 36px;
  overflow: hidden;
}
.cc-strip-svg {
  display: block;
}
.cc-portfolio {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
  gap: 8px;
  padding: 4px;
}
.cc-portfolio__card {
  background: #fff;
  border: 1px solid #E5E7EB;
  border-left-width: 3px;
  border-radius: 4px;
  padding: 8px 10px;
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.cc-portfolio__card--green {
  border-left-color: #10B981;
}
.cc-portfolio__card--yellow {
  border-left-color: #F59E0B;
}
.cc-portfolio__card--red {
  border-left-color: #DC2626;
}
.cc-portfolio__header {
  display: flex;
  align-items: center;
  gap: 6px;
}
.cc-portfolio__name {
  font-weight: 600;
  color: #1F2A44;
  font-size: 13px;
}
.cc-portfolio__dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
}
.cc-portfolio__dot--green {
  background: #10B981;
}
.cc-portfolio__dot--yellow {
  background: #F59E0B;
}
.cc-portfolio__dot--red {
  background: #DC2626;
}
.cc-portfolio__kpi {
  color: #6C757D;
  font-size: 11px;
}
.cc-portfolio__fever {
  height: 56px;
}
.cc-cap-ctrl {
  background: #fff;
  border: 1px solid #E5E7EB;
  border-radius: 4px;
  padding: 6px 8px;
  margin-bottom: 6px;
  font-size: var(--cc-insight-font, 12px);
}
.cc-cap-ctrl__label {
  font-weight: 600;
  color: #1F2A44;
  margin-bottom: 4px;
  font-size: calc(var(--cc-insight-font, 12px) - 1px);
}
.cc-cap-ctrl__row {
  display: flex;
  align-items: center;
  gap: 6px;
}
.cc-cap-ctrl__range {
  flex: 1 1 auto;
  min-width: 60px;
  accent-color: #E8612A;
  height: 18px;
}
.cc-cap-ctrl__num {
  width: 56px;
  padding: 2px 4px;
  border: 1px solid #E5E7EB;
  border-radius: 3px;
  font-size: calc(var(--cc-insight-font, 12px) - 1px);
  text-align: right;
}
.cc-cap-ctrl__num:focus {
  outline: 2px solid #E8612A;
  outline-offset: -2px;
}
.cc-cap-ctrl__hint {
  font-size: calc(var(--cc-insight-font, 12px) - 2px);
  color: #6C757D;
  margin-top: 3px;
}
.cc-fever-chart {
  background: #fff;
  border: 1px solid #E5E7EB;
  border-radius: 4px;
  padding: 2px;
  margin-top: 6px;
  min-height: 140px;
}
.cc-fever-full {
  display: block;
  width: 100%;
  height: 100%;
}
.cc-fever-full .cc-fever-axis path,
.cc-fever-full .cc-fever-axis line {
  stroke: #E5E7EB;
}
.cc-fever-full .cc-fever-axis text {
  fill: #6C757D;
}
.cc-fever-full .cc-fever-title {
  fill: #1F2A44;
  font-weight: 600;
}
.cc-root.cc-wide .cc-insight-panel {
  width: 280px;
}
.cc-root.cc-medium .cc-insight-panel {
  width: 220px;
}
.cc-root.cc-narrow .cc-body {
  flex-direction: column;
}
.cc-root.cc-narrow .cc-strip-toggle {
  width: 100%;
  flex-direction: row;
}
.cc-root.cc-narrow .cc-strip-toggle__label {
  writing-mode: horizontal-tb;
  transform: none;
  margin-top: 0;
  margin-left: 6px;
}
.cc-root.cc-narrow .cc-insight-panel {
  width: 100% !important;
  max-width: 100% !important;
  border-left: 0;
  border-top: 1px solid #E5E7EB;
}
.bfusion-landing {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 24px 28px;
  max-width: 640px;
  margin: 24px auto;
  background: #fff;
  border: 1px solid #E5E7EB;
  border-radius: 6px;
}
.bfusion-landing__logo {
  width: 80px;
  height: auto;
}
.bfusion-landing__title {
  margin: 0 0 8px;
  color: #1F2A44;
  font-size: 18px;
}
.bfusion-landing__description {
  margin: 0;
  color: #242424;
  font-size: 13px;
  line-height: 1.5;
}
.bfusion-landing__separator {
  height: 1px;
  background: #E5E7EB;
  margin: 10px 0;
}
.bfusion-landing__metadata {
  color: #6C757D;
  font-size: 11px;
}
.bfusion-empty {
  display: flex;
  align-items: center;
  justify-content: center;
  height: 100%;
}
.bfusion-empty__message {
  color: #6C757D;
  font-size: 13px;
  padding: 24px;
  text-align: center;
}
